import { auth } from '@/auth';
import { redirect } from 'next/navigation';
import DocumentsTable from '@/app/ui/documents-table';
import { PlusIcon } from '@heroicons/react/24/outline';

export default async function DocumentsPage() {
  // 1. Ambil data session
  const session = await auth();

  // 2. Proteksi Role: Jika bukan admin, tendang ke /dashboard
  if ((session?.user as any)?.role !== 'admin') {
    redirect('/dashboard');
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header Halaman */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-extrabold text-dcc-950 tracking-tight underline decoration-blue-500/30 decoration-4 underline-offset-4">
            DOKUMEN TERKONTROL
          </h1>
          <p className="text-sm text-slate-500 font-medium mt-1">
            Halaman khusus Administrator untuk pengelolaan Master List Dokumen.
          </p>
        </div>
        
        {/* Tombol ini hanya akan terlihat oleh admin karena halaman ini sudah terproteksi */}
        <button className="flex items-center justify-center gap-2 bg-dcc-600 text-white px-5 py-2.5 rounded-xl text-[14px] font-bold hover:bg-dcc-700 transition-all shadow-lg shadow-blue-600/20 active:scale-95">
          <PlusIcon className="w-5 h-5" />
          TAMBAH DOKUMEN
        </button>
      </div>

      {/* Main Table Component */}
      <DocumentsTable />
    </div>
  );
}